(()=>{"use strict";const $=id=>document.getElementById(id),I=window.CMI18n,inputs=[$("kg"),$("cm"),$("age"),$("sex")],out=["result","chipBmi","chipFat","chipLean","cBmi","cBf","cFat","cLean","cOther","barYouVal","barOtherVal"],num=n=>n.toLocaleString(I?.formatLocale||"en-US",{maximumFractionDigits:1}),say=(pair,values=[])=>I?.message?I.message(pair,values):pair.split("|")[0].replace(/\{(\d+)\}/g,(_,k)=>values[k]);function invalid(pair){out.forEach(id=>{$(id).textContent="\u2014"}),$("barYou").style.width="0%",$("barOther").style.width="0%",$("verdict").className="verdict warn",$("verdictText").textContent=say(pair),window.__summary=""}function render(){const[kg,cm,age]=inputs.slice(0,3).map(input=>input.value.trim()===""?NaN:Number(input.value)),sex=$("sex").value;if(![kg,cm,age].every(Number.isFinite)||kg<=0||cm<=0||age<18||!["male","female"].includes(sex)){invalid("Enter a finite positive weight and height, and an adult age of at least 18 years. This equation is not a child body-fat model.|\u8BF7\u8F93\u5165\u6709\u9650\u4E14\u5927\u4E8E\u96F6\u7684\u4F53\u91CD\u3001\u8EAB\u9AD8\uFF0C\u4EE5\u53CA\u81F3\u5C11 18 \u5C81\u7684\u6210\u4EBA\u5E74\u9F84\u3002\u672C\u516C\u5F0F\u4E0D\u9002\u7528\u4E8E\u513F\u7AE5\u4F53\u8102\u4F30\u7B97\u3002");return}const bmi=kg/(cm/100)**2,bf=1.2*bmi+.23*age-(sex==="male"?10.8:0)-5.4,other=bf+(sex==="male"?10.8:-10.8),fat=kg*(bf/100),lean=kg*(1-bf/100);if(![bmi,bf,fat,lean].every(Number.isFinite)||bf<0||bf>100){invalid("This input gives an estimate outside the physical 0\u2013100% range or supported numeric range. No body-composition estimate is shown.|\u8BE5\u8F93\u5165\u4F7F\u4F30\u7B97\u8D85\u51FA 0\u2013100% \u7684\u7269\u7406\u8303\u56F4\u6216\u53EF\u8868\u793A\u6570\u503C\u8303\u56F4\uFF0C\u56E0\u6B64\u4E0D\u663E\u793A\u8EAB\u4F53\u6210\u5206\u4F30\u7B97\u3002");return}$("result").textContent=num(bf)+" %";for(const id of["chipBmi","cBmi"])$(id).textContent=num(bmi);for(const id of["chipFat","cFat"])$(id).textContent=num(fat)+" kg";for(const id of["chipLean","cLean"])$(id).textContent=num(lean)+" kg";for(const id of["cBf","barYouVal"])$(id).textContent=num(bf)+" %";const otherValid=Number.isFinite(other)&&other>=0&&other<=100;for(const id of["cOther","barOtherVal"])$(id).textContent=otherValid?num(other)+" %":"\u2014";const mx=Math.max(bf,otherValid?other:0,1);$("barYou").style.width=bf/mx*100+"%",$("barOther").style.width=otherValid?other/mx*100+"%":"0%",$("verdict").className="verdict warn",$("verdictText").textContent=say("This is a population-equation estimate, not a direct body-composition measurement. It can be inaccurate for athletes, older adults, and many body types \u2014 treat the percentage as a rough guide, not a measured value.|\u8FD9\u662F\u4EBA\u7FA4\u65B9\u7A0B\u4F30\u7B97\uFF0C\u4E0D\u662F\u76F4\u63A5\u7684\u8EAB\u4F53\u6210\u5206\u6D4B\u91CF\u3002\u5BF9\u8FD0\u52A8\u5458\u3001\u8001\u5E74\u4EBA\u53CA\u591A\u79CD\u4F53\u578B\u53EF\u80FD\u4E0D\u51C6\u786E\uFF0C\u8BF7\u5C06\u767E\u5206\u6BD4\u89C6\u4E3A\u7C97\u7565\u53C2\u8003\uFF0C\u800C\u4E0D\u662F\u5B9E\u6D4B\u503C\u3002"),window.__summary=say("Estimated adult body fat {0}%; BMI {1}; estimated fat mass {2} kg and lean mass {3} kg.|\u6210\u4EBA\u4F53\u8102\u4F30\u7B97 {0}%\uFF1BBMI {1}\uFF1B\u4F30\u7B97\u8102\u80AA\u91CF {2} kg\u3001\u7626\u4F53\u91CD {3} kg\u3002",[num(bf),num(bmi),num(fat),num(lean)])}inputs.forEach(input=>input.addEventListener("input",render)),render()})();
